<template><div><div class="mb-6"><div class="eyebrow mb-2">Konfiguration</div><h1 class="page-heading">Firmeneinstellungen</h1><p class="muted mt-2">Diese Daten werden bei neuen Rechnungen als unveränderlicher Snapshot übernommen.</p></div><v-progress-linear v-if="loading" indeterminate/><v-form v-else ref="formRef" @submit.prevent="save"><v-row><v-col cols="12" lg="8"><v-card class="surface-card pa-5 pa-sm-7 mb-5"><h2 class="text-h6 font-weight-bold mb-5">Unternehmen & Kontakt</h2><v-text-field v-model="form.companyName" label="Firmenname" :rules="[required]"/><v-text-field v-model="form.street" label="Straße und Hausnummer" :rules="[required]"/><v-row dense><v-col cols="5"><v-text-field v-model="form.postalCode" label="PLZ" :rules="[required]"/></v-col><v-col cols="7"><v-text-field v-model="form.city" label="Ort" :rules="[required]"/></v-col></v-row><v-row dense><v-col cols="4"><v-select v-model="form.country" label="Land" :items="['DE','AT','CH','FR','NL']"/></v-col><v-col cols="8"><v-text-field v-model="form.email" label="E-Mail" type="email"/></v-col></v-row><v-text-field v-model="form.phone" label="Telefon"/></v-card><v-card class="surface-card pa-5 pa-sm-7"><h2 class="text-h6 font-weight-bold mb-5">Steuern & Bank</h2><v-row dense><v-col cols="12" sm="6"><v-text-field v-model="form.taxId" label="Steuernummer"/></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.vatId" label="USt-IdNr."/></v-col></v-row><v-text-field v-model="form.bankName" label="Bank"/><v-row dense><v-col cols="12" sm="8"><v-text-field v-model="form.iban" label="IBAN"/></v-col><v-col cols="12" sm="4"><v-text-field v-model="form.bic" label="BIC"/></v-col></v-row></v-card></v-col><v-col cols="12" lg="4"><v-card class="surface-card pa-5 pa-sm-6"><h2 class="text-h6 font-weight-bold mb-5">Rechnungsstandard</h2><v-text-field v-model="form.invoicePrefix" label="Nummernpräfix" hint="Beispiel: RE-2026-0001" persistent-hint/><v-select v-model="form.defaultCurrency" label="Standardwährung" :items="['EUR','CHF','USD','GBP']"/><v-text-field v-model.number="form.paymentTermsDays" label="Zahlungsziel in Tagen" type="number" min="0" max="365"/><v-file-input label="Logo (PNG/JPEG, max. 2 MB)" accept="image/png,image/jpeg" prepend-icon="mdi-image-outline" @update:model-value="readLogo"/><v-img v-if="form.logoDataUrl" :src="form.logoDataUrl" max-height="100" contain class="my-3"/><v-btn color="primary" type="submit" size="large" block class="mt-3" :loading="saving">Einstellungen speichern</v-btn></v-card></v-col></v-row></v-form></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api,apiMessage}from'../api/client';import{useUiStore}from'../stores/ui';const form=reactive({companyName:'',street:'',postalCode:'',city:'',country:'DE',email:'',phone:'',taxId:'',vatId:'',bankName:'',iban:'',bic:'',logoDataUrl:'',invoicePrefix:'RE',defaultCurrency:'EUR',paymentTermsDays:14});const loading=ref(true),saving=ref(false),formRef=ref<{validate():Promise<{valid:boolean}>}>(),ui=useUiStore();const required=(v:unknown)=>Boolean(String(v??'').trim())||'Pflichtfeld';onMounted(async()=>{try{Object.assign(form,(await api.get('/company-settings')).data)}catch(e){ui.notify(apiMessage(e),'error')}finally{loading.value=false}});async function save(){const v=await formRef.value?.validate();if(!v?.valid)return;saving.value=true;try{await api.put('/company-settings',form);ui.notify('Firmeneinstellungen gespeichert.')}catch(e){ui.notify(apiMessage(e),'error')}finally{saving.value=false}}function readLogo(value:File|File[]|null){const file=Array.isArray(value)?value[0]:value;if(!file)return;if(file.size>2_000_000){ui.notify('Das Logo darf maximal 2 MB groß sein.','error');return}const reader=new FileReader();reader.onload=()=>{form.logoDataUrl=String(reader.result)};reader.readAsDataURL(file)}</script>
